DECLARE @r TABLE(sp sysname NULL, db sysname NULL, ref sysname NULL, reftype sysname NULL, refdb sysname NULL, upd int);
DECLARE @sp sysname, @db sysname, @qn nvarchar(300), @sql nvarchar(max), @sql2 nvarchar(max);
DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT name, db FROM @n;
OPEN c; FETCH NEXT FROM c INTO @sp, @db;
WHILE @@FETCH_STATUS = 0
BEGIN
  SET @qn = N'dbo.' + @sp;
  SET @sql = N'SELECT d.referenced_entity_name, ISNULL(o.type_desc, CASE WHEN d.referenced_database_name IS NOT NULL THEN ''CROSS-DB'' ELSE ''UNRESOLVED'' END), ISNULL(d.referenced_database_name,''''), ISNULL(d.is_updated,0)
               FROM sys.dm_sql_referenced_entities(@name, ''OBJECT'') d LEFT JOIN sys.objects o ON o.object_id = d.referenced_id WHERE d.referenced_minor_id = 0';
  SET @sql2 = N'SELECT d.referenced_entity_name, ISNULL(o.type_desc, CASE WHEN d.referenced_database_name IS NOT NULL THEN ''CROSS-DB'' ELSE ''UNRESOLVED'' END), ISNULL(d.referenced_database_name,''''), -1
               FROM sys.sql_expression_dependencies d LEFT JOIN sys.objects o ON o.object_id = d.referenced_id WHERE d.referencing_id = OBJECT_ID(@name)';
  BEGIN TRY
    IF @db = 'CSTL_ACCDB_Unicorn'
      INSERT INTO @r(ref, reftype, refdb, upd) EXEC CSTL_ACCDB_Unicorn.sys.sp_executesql @sql, N'@name nvarchar(300)', @name = @qn;
    ELSE
      INSERT INTO @r(ref, reftype, refdb, upd) EXEC CSTL_ERPDB_Unicorn.sys.sp_executesql @sql, N'@name nvarchar(300)', @name = @qn;
  END TRY
  BEGIN CATCH
    IF @db = 'CSTL_ACCDB_Unicorn'
      INSERT INTO @r(ref, reftype, refdb, upd) EXEC CSTL_ACCDB_Unicorn.sys.sp_executesql @sql2, N'@name nvarchar(300)', @name = @qn;
    ELSE
      INSERT INTO @r(ref, reftype, refdb, upd) EXEC CSTL_ERPDB_Unicorn.sys.sp_executesql @sql2, N'@name nvarchar(300)', @name = @qn;
  END CATCH
  UPDATE @r SET sp = @sp, db = @db WHERE sp IS NULL;
  FETCH NEXT FROM c INTO @sp, @db;
END
CLOSE c; DEALLOCATE c;
SELECT 'EXISTS' AS k, name, db, '' AS ref, '' AS reftype, '' AS refdb, '0' AS upd FROM @n
UNION ALL
SELECT DISTINCT 'DEP', sp, db, ref, reftype, refdb, CAST(upd AS varchar(2)) FROM @r
ORDER BY 1, 2, 4;
